import { createPool } from './index.ts';
import { fileDb } from './fileDb.ts';
import { initializeDatabaseSchema } from './init.ts';

const pool = createPool();

export const isPgConfigured = () => {
  return true;
};

class AsyncSemaphore {
  private tasks: (() => void)[] = [];
  private count = 0;
  private max: number;
  constructor(max: number) {
    this.max = max;
  }

  async acquire(): Promise<void> {
    if (this.count < this.max) {
      this.count++;
      return;
    }
    await new Promise<void>((resolve) => this.tasks.push(resolve));
    this.count++;
  }

  release(): void {
    this.count--;
    if (this.tasks.length > 0) {
      const next = this.tasks.shift();
      if (next) next();
    }
  }
}

const pgSemaphore = new AsyncSemaphore(5);

export async function executePg(sql: string, params: any[] = []): Promise<any[]> {
  await pgSemaphore.acquire();
  try {
    let attempts = 0;
    const maxAttempts = 3;
    while (attempts < maxAttempts) {
      try {
        const currentPool = createPool();
        const res = await currentPool.query(sql, params);
        return res.rows || [];
      } catch (e: any) {
        attempts++;
        const errStr = (e?.message || '').toLowerCase();
        const isConnError = errStr.includes('econnreset') || errStr.includes('etimedout') || errStr.includes('timeout') || errStr.includes('terminated') || errStr.includes('closed') || errStr.includes('connection');
        const isMaxConn = errStr.includes('emaxconnsession') || errStr.includes('too many clients') || errStr.includes('connection limit');

        if ((isConnError || isMaxConn) && attempts < maxAttempts) {
          await new Promise((r) => setTimeout(r, attempts * 800 + Math.random() * 400));
          continue;
        }

        if (e.message && e.message.includes('does not exist')) {
          try {
            if (e.message.includes('avatar_url') && e.message.includes('reps')) {
              const currentPool = createPool();
              await currentPool.query('ALTER TABLE reps ADD COLUMN IF NOT EXISTS avatar_url TEXT;').catch(() => {});
              const resRetry = await currentPool.query(sql, params);
              return resRetry.rows || [];
            }
            await initializeDatabaseSchema();
            const currentPool = createPool();
            const res2 = await currentPool.query(sql, params);
            return res2.rows || [];
          } catch (innerErr) {}
        }

        if (attempts >= maxAttempts) {
          console.error('PostgreSQL query error after retries:', e.message, 'SQL:', sql);
          throw e;
        }
      }
    }
    return [];
  } finally {
    pgSemaphore.release();
  }
}

export const dbStore = fileDb;
